"""Plain Markdown artifacts with full costs, months, regimes and evidence limits."""
import json
from pathlib import Path


def fmt(x,n=3):return '—' if x is None else f'{x:.{n}f}'


def write(s,out):
    out=Path(out);a=s['data_audit']
    comparison=['# Aura 6 · Полное сравнение','','Все строки — отдельная стратегия/вариант/сторона/TF, не портфель. Комиссия 10 bps/сторону, проскальзывание 5 bps/сторону, модельный полный спред 2 bps; стресс умножает все расходы. Funding: реальные ставки с 2026-08-01, до этого явно модельный дебет 1 bp/8h (×1.5/×2 в stress). M — количество модельных начислений funding. Результаты с M>0 не подтверждают реальную прибыльность. Позиции одного семейства/варианта/стороны/TF не пересекаются; разные группы не суммируются в доходность.','','| TF | Семейство | Вариант | Сторона | Период | Расходы | Сигналы / входы / закрыто | WR % | PF | E[R] | 95% CI E[R] | PnL USDT | DD USDT / R | Funding USDT / M |','|---|---|---|---|---|---:|---:|---:|---:|---:|---|---:|---:|---:|']
    for r in s['results']:
        ci=r['uncertainty']['expectancy_R'];ci='['+'; '.join(fmt(v) for v in ci)+']' if ci else 'INSUFFICIENT_EVIDENCE'
        comparison.append(f"| {r['frame']} | {r['strategy']} | {r['variant']} | {r['side']} | {r['stage']} | ×{r['cost']} | {r['signals']}/{r['entered']}/{r['closed']} | {fmt(r['win_rate']*100 if r['win_rate'] is not None else None,1)} | {fmt(r['profit_factor'])} | {fmt(r['expectancy_R'])} | {ci} | {fmt(r['pnl_usdt'],2)} | {fmt(r['max_drawdown_usdt'],2)} / {fmt(r['max_drawdown_R'])} | {fmt(r['funding_usdt'],2)} / {r['modeled_funding_settlements']} |")
    (out/'COMPARISON_RU.md').write_text('\n'.join(comparison)+'\n')
    months=['# Aura 6 · Месяцы и режимы','','Месяц UTC — когорта сигнала; режим только по ER20 на момент сигнала, не ретроспективный ярлык. Все расходы и пустые группы хранятся в summary.json.gz. Ниже только строки с принятыми гипотезами при базовых расходах.','','| TF / семейство / вариант / сторона | Этап | Месяц или режим | Сигналы / входы / закрыто | PF | E[R] | PnL USDT | Max DD R | Funding M |','|---|---|---|---:|---:|---:|---:|---:|---:|']
    for r in s['results']:
        if r['cost']!=1:continue
        for kind in ['months','regimes']:
            for label,m in r[kind].items():
                months.append(f"| {r['frame']} / {r['strategy']} / {r['variant']} / {r['side']} | {r['stage']} | {label} | {m['signals']}/{m['entered']}/{m['closed']} | {fmt(m['profit_factor'])} | {fmt(m['expectancy_R'])} | {fmt(m['pnl_usdt'],2)} | {fmt(m['max_drawdown_R'])} | {m['modeled_funding_settlements']} |")
    (out/'MONTHS_REGIMES_RU.md').write_text('\n'.join(months)+'\n')
    walk=['# Aura 6 · Expanding walk-forward','','Восемь квартальных проверок с 2023-10 до 2025-10. Перед каждым тестом прошлое обучение заканчивается за 49 свечей до границы. Никакого переноса гипотез через границы; 250 свечей прогрева берутся из прошлого. Правила не оптимизируются. Пригодность обучающей группы вычисляется только по прошлому, тестовые результаты не выбирают победителя. При нехватке funding прошлые результаты остаются модельными.','','| TF / семейство / вариант / сторона | Test start UTC seconds | Допуск по прошлым модельным данным | Train closed | Test closed | Test PF | Test E[R] |','|---|---:|---|---:|---:|---:|---:|']
    for w in s['walk_forward']:
        if not w['test']['signals']:continue
        walk.append(f"| {w['frame']} / {w['strategy']} / {w['variant']} / {w['side']} | {w['test_start']} | {w['eligible_prior_only']} | {w['train_closed']} | {w['test']['closed']} | {fmt(w['test']['profit_factor'])} | {fmt(w['test']['expectancy_R'])} |")
    (out/'WALK_FORWARD_RU.md').write_text('\n'.join(walk)+'\n')
    main=['# AURA 6.0 · Signal Research & Hunter','','## Результат','','**'+s['verdict']+'. Все стратегии UNVALIDATED, реестр CONFIRMED пуст. Вероятность TP раньше SL не рассчитывается.**', '', 'Кандидаты, прошедшие весь исследовательский допуск с полными реальными ставками funding: '+str(len(s['forward_candidates']))+'. Отдельные кандидаты только в допущениях о недостающем funding: '+str(len(s['cost_model_candidates']))+'; они не допускаются к CONFIRMED.', '', '## История и качество','','Источник только Bitget BTCUSDT USDT-M, публичный v2 history-candles. '+str(a['base_candles'])+' реальных 5m-свечей с 2021-08-01 до 2026-10-29 UTC, конец не включая. Пропусков '+str(a['missing_candles'])+'. Данные 15m/1h/4h получены точным агрегированием полного набора 5m в UTC. Количество свечей: `'+json.dumps(a['frame_candles'])+'`. Никаких синтетических баров и скрытого объединения бирж. Неполные агрегаты отбрасываются, прогрев после разрыва сбрасывается, исход открытой гипотезы при разрыве UNKNOWN. Все месячные файлы gzip и SHA-256 зафиксированы в data/hunter6/acquisition.json. Отдельный DATA_AUDIT.json содержит границы, качество и покрытие funding.', '', 'История funding API оказалась ограничена примерно 90 днями: '+str(a['funding_rows'])+' реальных ставок с 2026-08-01. До этого **нет достоверной полной истории funding**. Для сравнительных исследований используется явная модель: дебет 1 bp за 8h без выдуманного дохода, с 1.5×/2× stress; каждый исход содержит missing_funding_settlements. Реальные ставки считаются с OHLC-прокси номинала, а не настоящей mark price; неопределённые граничные кредиты исключены. Это не точное воспроизведение расчётов биржи. Отсутствующее покрытие блокирует допуск к проверенной рекомендации.', '', 'Официальные ссылки: https://www.bitget.com/docs/catalog/classic-contract-market/classic-contract-market (history-candles и history-fund-rate); https://www.bitget.com/docs/catalog/market/derivatives (funding history last 90 days). Не используются личные/торговые endpoints и API-ключи.', '', '## Шесть независимых семейств','','1. Trend Pullback: EMA50/200, ER20, откат к EMA20, направленное закрытие за предыдущий экстремум, RSI и объём. Минимальный стоп 2 ATR с сохранением структуры, TP 2.5 R, максимум 48 свечей.','2. Breakout + Retest: уровень диапазона предыдущих 20 свечей известен до отдельной свечи пробоя; закрытый пробой +0.2 ATR с объёмом, отдельный закрытый ретест ±0.5 ATR и возврат +0.1 ATR. Стоп ≥2 ATR, TP 2 R, максимум 32 свечи.','3. Momentum / Volatility Expansion: EMA20/50, TR 1.5–3 предыдущих ATR, объём ≥1.5 среднего, направленное тело ≥60%, закрытый пробой диапазона и RSI. SL 1.8 ATR, TP 2.5 R, максимум 24 свечи.','4. Mean Reversion: предыдущий выход за Bollinger20 ±2 population stddev, RSI<30/>70, ER≤0.3, закрытый возврат внутрь полос с восстановлением RSI. Структурный стоп ≥1.5 ATR, цель — известная mean20, максимум 24 свечи.','5. Market Structure / Liquidity Sweep: прокол прошлого 20-свечного экстремума >0.1 ATR, возврат закрытием, тень ≥тела и объём. Это прокси ликвидности, не наблюдаемые стоп-ордера. Стоп за экстремумом ≥1.5 ATR, TP 2 R, максимум 32 свечи.','6. Range Rejection: ER≤0.2, EMA separation≤0.5 ATR, прошлый 40-свечный диапазон ≥4 ATR, отбой от внешних 20%, RSI. Стоп за диапазоном ≥1.5 ATR, цель — известная середина, максимум 24 свечи.', '', 'BASE и один заранее фиксированный STRICT: усиление ER/объёма/ширины Bollinger, без перебора параметров. Точные правила в research/hunter6/protocol.json и app/hunter/rules.json, математическая реализация в app/hunter/engine.py. Один и тот же engine используется исследованиями и сервером. Входы/цели фиксируются при закрытии; никакой информации следующей свечи в генераторе. Отмена: срок следующей свечи, выход из Entry-zone ±0.5 ATR, пересечение SL/TP, устаревшие/противоречивые данные. Минимальный net R/R 1.5 включает модельные расходы и резерв funding 1 bp/8h максимального удержания.', '', '## Исполнение и метрики','','Исследование: next-open после формирования, только внутри зоны и между SL/TP. Entry/exit с неблагоприятными spread/slip и комиссиями обеих сторон. SL/TP в одной свече — SL первым; гэп за SL ухудшает цену, гэп за TP не даёт улучшения. Последовательность строго по времени. Пропуск времени или конец выборки — UNKNOWN, не прибыль и не нулевой доход. TIMEOUT закрывается по закрытию последней допустимой свечи. Одна гипотеза в одной группе одновременно; OVERLAP и NO_FILL считаются отдельно.', '', 'PnL — исследовательский результат 1 BTC. R=net PnL/исходный риск Entry−SL, не доля капитала. Направления и семейства не объединяются в доходность портфеля; процентов доходности и сложного процента нет. WR по положительному net результату, PF без убытков не определён. DD по сумме закрытых результатов, не mark-to-market. Средняя прибыль/убыток, комиссии/funding и все исходы содержатся в gzip JSON.', '', '## Хронология и защита от подгонки','','Train: 2021-10–2023-10. Validation: 2023-10–2024-10. Test: 2024-10–2025-10. Final: 2025-10–2026-10-29. Даты UTC, концы исключены. Список выбранных по train+validation записывается в selection-TF.json до открытия test/final. Test может отвергнуть, но не выбрать новую стратегию. Ни максимальный final PnL, ни результат STRICT в финале не меняют параметры.', '', '**Final — отдельный хронологический тест этого кода, но НЕ глобально независимая история:** период уже использовался прошлым Aura Research/Strategy Lab. Поэтому даже хороший final не означает VALIDATED. Исходный протокол создан до новых performance-прогонов; ограничения funding выявлены при загрузке и отражены до оценки прибыльности. Никаких новых параметров после результатов.', '', 'Допуск: train≥100 закрытых на сторону/TF, validation/test≥50, PF≥1.2, положительная нижняя 95% граница E[R], положительных месяцев ≥60%, E[R] при ×2 расходах >0. Реальное покрытие funding и независимость проверяются отдельно; общий реестр APPROVED не заполняется автоматически.', '', 'Интервалы: 1000 детерминированных resampling целых календарных блоков по 14 дней (с пустыми блоками), 95% percentile E[R]/WR/PF. Нет интервала при <30 закрытых или <10 активных блоках. Перекрытие между блоками, режимная нестационарность, повторное использование истории и множество сравнений сохраняют неопределённость; вероятностью прибыльной сделки CI не является.', '', '[Полное сравнение](COMPARISON_RU.md) · [Месяцы и режимы](MONTHS_REGIMES_RU.md) · [Walk-forward](WALK_FORWARD_RU.md) · [Машинные метрики](summary.json.gz) · [Все гипотезы](trades.json.gz).', '', '## Сверка и границы переноса в LIVE','','Сохранённый PUBLIC_PROBE.json: девять сравнений по десять свечей 15m/1h/4h; OHLC совпали везде. В двух исторических выборках 4h объём расходится с суммой 5m: максимум 0.001414% и 0.067543%. Причина не установлена, данные не исправлялись. Это ограниченная выборочная сверка, не проверка каждого бара. Два публичных цикла с перезапуском показали свежие четыре TF, сохранение журнала и ноль alerts; это не непрерывный forward-тест.','','Исследование использует агрегированные бары и EMA с расширяющимся префиксом, LIVE — 260 native закрытых баров и повторный прогрев. Одинаковый код не доказывает равенство входных данных и EMA seed. Перенос статистики в LIVE не подтверждён. Реестр требует отдельный input_contract=BITGET_NATIVE_260_CLOSED_BARS_V1 вместе с независимым evidence hash: допуск по архивному контракту запрещён. Поставляемый реестр пуст.','','## Signal Hunter: границы готовности','','Реализован отдельный FastAPI app.hunter.main:app, не подключённый к Aura 5.0. Только фиксированные публичные GET Bitget. Состояния WATCH / CONFIRMED / NO TRADE; CONFIRMED требует точного model SHA, направления, TF, независимого evidence hash и VALIDATED из локального реестра. Поставляемый eligibility.json пуст. WATCH / UNVALIDATED не озвучиваются. Нет произвольных процентов уверенности, торговых API, ключей аккаунта, виртуального кошелька или кнопок исполнения.', '', 'Наблюдатель использует закрытые свечи и Bid/Ask не старше 5 секунд, ограничивает спред/противоречия, отменяет устаревшие/вышедшие из зоны планы. Выделенная SQLite хранит обнаружение, исходы, watermarks и одноразовый outbox; restart не сбрасывает дедупликацию. Неясные касания в свече обнаружения UNKNOWN, поскольку свеча содержит цены до фактического обнаружения. Гипотетический результат не выдаётся за исполнение Demo.', '', 'Мобильная отдельная страница: карточки, TF, свежесть Bid/Ask, журнал и опциональный Web Audio с LONG/SHORT, громкостью и user gesture. Дедуп по версии/стратегии/стороне/TF/времени сигнала сохраняется и переживает сброс sequence DB. Звук не обещается в закрытой/спящей вкладке. Постоянные push требуют отдельного Service Worker/Web Push/VAPID/outbox delivery дизайна; здесь внешние push и платные сервисы не включены.', '', 'Для будущего отдельно разрешённого запуска: задать AURA_HUNTER_PASSWORD, выделенный AURA_HUNTER_STATE_PATH и AURA_HUNTER_OBSERVE=true; один uvicorn worker, постоянное хранилище и непрерывно работающий сервер. Без owner-пароля доступ закрыт, наблюдение выключено по умолчанию. Render Free/sleep не обеспечивает непрерывный сбор. Никаких изменений существующего Render в этой работе.', '', '```bash','PYTHONPATH=. python -m scripts.hunter6_download data/hunter6','PYTHONPATH=. python -m research.hunter6.run docs/aura6 data/hunter6','python -m uvicorn app.hunter.main:app --host 127.0.0.1 --port 8086 --workers 1','```', '', 'Реальных готовых рекомендаций для Bitget Demo пока нет: нет независимого подтверждённого преимущества. Пользователь может изучать WATCH и статистику, но Aura не отправляет сделки. Для допуска нужны новые forward-данные, реальные funding/расходы, независимая проверка и ручное обновление доказательного реестра после review. Deploy/merge/production/PAPER/Active43 не выполнялись. Результаты тестов/CI и точный SHA публикуются в Draft PR.']
    (out/'REPORT_RU.md').write_text('\n'.join(main)+'\n')
